        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
        "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
        CONSTRAINT "PK_conversations" PRIMARY KEY ("ConversationID"),
        CONSTRAINT "FK_conversations_users_User1ID" FOREIGN KEY ("User1ID") REFERENCES users ("UserID") ON DELETE RESTRICT,
        CONSTRAINT "FK_conversations_users_User2ID" FOREIGN KEY ("User2ID") REFERENCES users ("UserID") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
