        CONSTRAINT "FK_chat_calls_users_CallerID" FOREIGN KEY ("CallerID") REFERENCES users ("UserID") ON DELETE RESTRICT,
        CONSTRAINT "FK_chat_calls_users_ReceiverID" FOREIGN KEY ("ReceiverID") REFERENCES users ("UserID") ON DELETE RESTRICT
