DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260924012116_SeedDefaultChatStickers') THEN
    PERFORM setval(
        pg_get_serial_sequence('sticker_packs', 'StickerPackID'),
        GREATEST(
            (SELECT MAX("StickerPackID") FROM sticker_packs) + 1,
            nextval(pg_get_serial_sequence('sticker_packs', 'StickerPackID'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('stickers', 'StickerID'),
        GREATEST(
            (SELECT MAX("StickerID") FROM stickers) + 1,
            nextval(pg_get_serial_sequence('stickers', 'StickerID'))),
        false);
    END IF;
END $EF$;

