DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106070040_AddCourseFreeClassification') THEN
    UPDATE courses SET "IsFree" = ("Price" <= 0);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261106070040_AddCourseFreeClassification') THEN
    DO $$
    BEGIN
        IF NOT EXISTS (
            SELECT 1 FROM pg_constraint
            WHERE conname = 'CK_courses_FreePriceConsistency'
              AND conrelid = 'courses'::regclass
        ) THEN
            ALTER TABLE courses
            ADD CONSTRAINT "CK_courses_FreePriceConsistency"
            CHECK (("IsFree" = TRUE AND "Price" = 0) OR ("IsFree" = FALSE AND "Price" > 0));
        END IF;
    END $$;
    END IF;
END $EF$;

