DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261114160000_AddVoiceJourneyAndAiEntitlements') THEN


    -- =====================================================
    -- 1. ADD MISSING COLUMNS TO VOICE LESSONS
    -- =====================================================

    ALTER TABLE voice_lessons
        ADD COLUMN IF NOT EXISTS "DocumentUrl" varchar(1500);

    ALTER TABLE voice_lessons
        ADD COLUMN IF NOT EXISTS "DocumentTitle" varchar(200);


    -- =====================================================
    -- 2. SYNCHRONIZE EXISTING VOICE JOURNEY COLUMNS
    -- =====================================================

    ALTER TABLE voice_roadmaps
        ALTER COLUMN "SourcePracticeSessionId" DROP NOT NULL;

    ALTER TABLE voice_roadmap_items
        ADD COLUMN IF NOT EXISTS "LessonId" integer;


    -- =====================================================
    -- 3. ENSURE VOICE JOURNEY INDEXES
    -- =====================================================

    CREATE UNIQUE INDEX IF NOT EXISTS
        "IX_voice_profiles_LearnerId"
        ON voice_profiles ("LearnerId");

    CREATE UNIQUE INDEX IF NOT EXISTS
        "IX_voice_roadmaps_LearnerId_Version"
        ON voice_roadmaps ("LearnerId", "Version");

    CREATE UNIQUE INDEX IF NOT EXISTS
        "IX_voice_roadmap_items_RoadmapId_DayNumber"
        ON voice_roadmap_items ("RoadmapId", "DayNumber");

    CREATE UNIQUE INDEX IF NOT EXISTS
        "IX_voice_skills_SkillCode"
        ON voice_skills ("SkillCode");

    CREATE UNIQUE INDEX IF NOT EXISTS
        "IX_voice_skill_model_mappings_SkillId_ModelLabel"
        ON voice_skill_model_mappings ("SkillId", "ModelLabel");

    CREATE INDEX IF NOT EXISTS
        "IX_voice_roadmap_items_LessonId"
        ON voice_roadmap_items ("LessonId");

    CREATE INDEX IF NOT EXISTS
        "IX_voice_exercise_attempts_LearnerId_ExerciseId_CreatedAt"
        ON voice_exercise_attempts
           ("LearnerId", "ExerciseId", "CreatedAt");

    CREATE INDEX IF NOT EXISTS
        "IX_voice_diagnostic_attempts_LearnerId_CreatedAt"
        ON voice_diagnostic_attempts
           ("LearnerId", "CreatedAt");

    CREATE INDEX IF NOT EXISTS
        "IX_voice_recommendation_snapshots_LearnerId_CreatedAt"
        ON voice_recommendation_snapshots
           ("LearnerId", "CreatedAt");


    -- =====================================================
    -- 4. CREATE AI ENTITLEMENTS TABLE
    -- =====================================================

    CREATE TABLE IF NOT EXISTS voice_ai_entitlements
    (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

        "LearnerId" integer NOT NULL,

        "SourceType" varchar(30) NOT NULL,

        "SourceCourseId" integer,

        "SourceEnrollmentId" integer,

        "SourcePaymentItemId" integer,

        "SourceGrantId" bigint,

        "GrantedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,

        "ExpiresAt" timestamptz,

        "Status" varchar(20) NOT NULL DEFAULT 'ACTIVE',

        "RevokedAt" timestamptz,

        "RevocationReason" varchar(200)
    );


    -- =====================================================
    -- 5. CREATE AI ENTITLEMENTS INDEXES
    -- =====================================================

    CREATE INDEX IF NOT EXISTS
        "IX_voice_ai_entitlements_LearnerId_Status_ExpiresAt"
        ON voice_ai_entitlements
        ("LearnerId", "Status", "ExpiresAt");

    CREATE UNIQUE INDEX IF NOT EXISTS
        "IX_voice_ai_entitlements_SourceGrantId"
        ON voice_ai_entitlements ("SourceGrantId")
        WHERE "SourceGrantId" IS NOT NULL;

    CREATE UNIQUE INDEX IF NOT EXISTS
        "IX_voice_ai_entitlements_SourcePaymentItemId"
        ON voice_ai_entitlements ("SourcePaymentItemId")
        WHERE "SourcePaymentItemId" IS NOT NULL;


    -- =====================================================
    -- 6. BACKFILL EXISTING AI GRANTS
    -- =====================================================

    INSERT INTO voice_ai_entitlements
    (
        "LearnerId",
        "SourceType",
        "SourceCourseId",
        "SourceEnrollmentId",
        "SourcePaymentItemId",
        "SourceGrantId",
        "GrantedAt",
        "ExpiresAt",
        "Status"
    )
    SELECT
        g."LearnerId",

        CASE
            WHEN g."SourceType" = 'DIRECT_PURCHASE'
                THEN 'AI_PURCHASE'
            ELSE 'MC_GIFT'
        END,

        g."CourseId",
        g."SourceEnrollmentId",
        g."SourcePaymentItemId",
        g."GrantId",
        g."GrantedAt",
        g."ExpiresAt",

        CASE
            WHEN g."ExpiresAt" IS NULL
                 OR g."ExpiresAt" > CURRENT_TIMESTAMP
                THEN 'ACTIVE'
            ELSE 'EXPIRED'
        END

    FROM course_access_grants g

    WHERE g."SourceType" IN
    (
        'GIFT',
        'DIRECT_PURCHASE',
        'LEGACY'
    )

    AND NOT EXISTS
    (
        SELECT 1
        FROM voice_ai_entitlements v
        WHERE v."SourceGrantId" = g."GrantId"
    );


    END IF;
END $EF$;

